import json
from pathlib import Path
OUT=Path(__file__).resolve().parent
MASTER='''基于输入的真实Blender clay白模，生成一张用于装修灵感讨论的专业家居杂志摄影级客厅图像。白模是唯一的建筑、尺度、占位和相机约束，不是风格模板。
硬约束：保持全部空间边界、墙角和墙顶线、门窗的位置与尺度、北侧飘窗开口和平台深度/高度、全部窗框和竖梃数量位置；不扩建房间，不变成落地玻璃墙，不新增任何门窗、柱或墙。保留真实比例、动线及可见标高关系。画幅1536×1024，保持原3:2相机透视与裁切，28mm自然室内视角、视高1.55m。不得变焦或转动相机。
会客区锁定：左侧三人沙发和右侧窗前双人沙发仍在原位置与朝向，保留两组独立座位、各自占位与二者之间的间隙、原边柜的位置和中央茶几的功能区域。不同款式可以改变细节曲线，但不能大幅移动/缩放家具、把两组座位合为L形沙发，或者遮住窗与原通道。全屋平面不可改。
本机位看不到次主卧门、休闲平台、楼梯和电视墙，不在前方凭空加入它们；窗外只是柔和背景，不确认具体景观。保持室内平顶，不生成复杂吊顶、天窗、夸张灯带或新的重装饰背景墙。
统一住宅风格：浅白蜡木/浅自然木、暖白墙、米白/燕麦/浅灰米织物。明亮干净、柔和日光、温暖但不泛黄，家庭居住感而非酒店样板间，北欧与日式克制自然。材质真实有触感，木纹、布艺、地面细节可信，阳光层次不过曝，家具设计成熟有辨识度。适量装饰，避免堆满小摆件；无文字、标识、水印。
三张候选必须在主要家具形态、茶几构造、材料组合及会客区设计表达上有根本区别，而非仅换抱枕、植物、挂画。本次只输出当前指定的一张版本。以下版本定义是最高的风格自由度约束。
'''
VERSIONS={
'FAITHFUL':'''版本FAITHFUL：以原模型为最忠实的几何和家具形态对照。保留左三人、右双人的方正厚实扶手沙发轮廓与靠背结构、两层长方形细腿茶几和原三抽屉边柜，数量尺度朝向与白模一致，仅把表面升级为燕麦亚麻布、自然浅白蜡木、暖白细纹墙和浅木条地板。白蜡木茶几仍是细腿、矩形双层结构，不改成低台、石块、圆几或组合桌。以低对比自然地毯和少量织物提升真实生活质感，装饰非常克制。基准图应清楚呈现模型原始家具形态，主要家具只允许很轻的边缘质感软化。''',
'DESIGNER':'''版本DESIGNER：在相同两组沙发功能占位和窗口关系下，给出明显不同于原厚扶手细腿家具的成熟现代家具语言。两组沙发采用低矮整合的浅白蜡木平台底座、薄直木扶手和厚实有层次的燕麦软包坐靠垫，横向线条精简，仍保持原占位与各自朝向，绝不延长成连体转角。中央茶几在原区域和总包络内改为一张低矮整合式矩形木石茶台：细哑光暖白石面搭浅白蜡木实体低底座或轻悬挑面，取消原细腿双层架结构。原边柜位置保留，造型简化为低矮平整木面。可用浅暖灰哑光大幅面石质/微水泥观感地面搭大型平织燕麦地毯、自然轻薄窗帘形成冷暖和软硬层次。重点是结构性家具设计、木石材料搭配和横向住宅尺度，不是增加摆件；浅木、暖白、米灰统一，日光柔和。''',
'CREATIVE':'''版本CREATIVE：仍保持左三人、右双人两个独立沙发的原功能区、尺度、朝向与所有建筑约束，积极探索与原方盒沙发及DESIGNER平台家具均不同的雕塑感自然木住宅语言。沙发使用清晰可见的浅白蜡木开放侧框、弧线扶手与圆润连续的燕麦布艺靠背，形成轻盈木骨架与柔软座垫对比；靠背可柔化成弧形但必须停留在原矩形包络内、保留座位数量和通道。中央茶几原占位里采用大小错落的两件低有机圆角木桌组合，总占地不超出原茶几功能区，原细腿双层矩形茶几不再出现，也不采用DESIGNER的整块石质矩形台。地面为浅自然木，地毯探索低饱和织物的有机柔和轮廓，墙面保持暖白，窗边用可撤除的薄软垫/轻织物提供亲切氛围，绝不新建窗柜或抬高平台。用有辨识度的弧线、开放木框和错落茶几制造核心差异，装饰少量，家庭感舒适、不网红、不重侘寂、不奢华。'''
}
jobs=[];pack=['# LIVINGROOM PROMPT PACK V2','', '范围：ONLY A1。各版本直接使用同一Blender clay，不将AI图当几何源。','', '## 公共硬约束', '', MASTER]
for key,addon in VERSIONS.items():
 prompt=MASTER+'\n'+addon+'\n只生成一张完整3:2图像，严格保持参考的相机及建筑透视。'
 pf=OUT/(key+'_PROMPT.txt');pf.write_text(prompt);jobs.append(dict(id='A1_'+key,version=key,input=str(OUT/'LIVINGROOM_A1_BASE_REFERENCE.png'),prompt_file=str(pf),output=str(OUT/('LIVINGROOM_A1_'+key+'.png'))))
 pack.extend(['','## A1_'+key,'',addon,'','输入：LIVINGROOM_A1_BASE_REFERENCE.png；输出：LIVINGROOM_A1_'+key+'.png'])
(OUT/'LIVINGROOM_PROMPT_PACK_V2.md').write_text('\n'.join(pack)+'\n');(OUT/'A1_JOBS.json').write_text(json.dumps(jobs,ensure_ascii=False,indent=2)+'\n')
print(json.dumps(dict(prompts=3,variants=list(VERSIONS),structural_furniture_differences=True)))
